import { Injectable, CanActivate, ExecutionContext, ForbiddenException } from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { ROLES_KEY } from './roles.decorator';
import { Role } from './role.enum';

@Injectable()
export class RolesGuard implements CanActivate {
  constructor(private readonly reflector: Reflector) {}

  canActivate(context: ExecutionContext): boolean {
    const requiredRoles = this.reflector.getAllAndOverride<Role[]>(ROLES_KEY, [
      context.getHandler(),
      context.getClass(),
    ]);

    // If route has no @Roles declaration, permit access (authenticated by JwtAuthGuard)
    if (!requiredRoles || requiredRoles.length === 0) {
      return true;
    }

    const { user } = context.switchToHttp().getRequest();

    if (!user || !user.roles) {
      throw new ForbiddenException('Access denied: Missing role credentials');
    }

    const hasPermission = requiredRoles.some((role) => user.roles.includes(role));

    if (!hasPermission) {
      throw new ForbiddenException(
        `Insufficient privileges: Requires [${requiredRoles.join(', ')}]`
      );
    }

    return true;
  }
}

'use server';

import { revalidateTag } from 'next/cache';
import { z } from 'zod';

const UpdateCourseSchema = z.object({
  courseId: z.string().min(1),
  title: z.string().min(3).max(120),
  syllabusJson: z.string(),
  isPublished: z.boolean(),
});

export type ActionState = {
  success: boolean;
  message?: string;
  errors?: Record<string, string[]>;
};

export async function updateCourseAction(
  prevState: ActionState,
  formData: FormData
): Promise<ActionState> {
  const validated = UpdateCourseSchema.safeParse({
    courseId: formData.get('courseId'),
    title: formData.get('title'),
    syllabusJson: formData.get('syllabusJson'),
    isPublished: formData.get('isPublished') === 'true',
  });

  if (!validated.success) {
    return {
      success: false,
      errors: validated.error.flatten().fieldErrors,
    };
  }

  const { courseId, title, syllabusJson, isPublished } = validated.data;

  const res = await fetch(`${process.env.API_GATEWAY_URL}/courses/${courseId}`, {
    method: 'PATCH',
    headers: {
      'Content-Type': 'application/json',
      'X-Internal-Secret': process.env.INTERNAL_SERVICE_SECRET || '',
    },
    body: JSON.stringify({ title, syllabusJson, isPublished }),
  });

  if (!res.ok) {
    return { success: false, message: 'Failed to update remote course record' };
  }

  // Atomically purge edge cache for this course and the catalog list
  revalidateTag(`course-${courseId}`, 'default');
  revalidateTag('catalog-list', 'default');

  return { success: true, message: 'Course updated and edge cache purged.' };
}

import { useState, useEffect, useMemo } from "react";

export interface AnalyticsMetric {
  timestamp: string;
  revenue: number;
  activeUsers: number;
  conversionRate: number;
}

export function useDashboardMetrics(intervalMs: number = 5000) {
  const [dataPoints, setDataPoints] = useState<AnalyticsMetric[]>([]);
  const [isLoading, setIsLoading] = useState<boolean>(true);

  useEffect(() => {
    let mounted = true;
    const fetchMetrics = async () => {
      try {
        const res = await fetch("/api/analytics/realtime");
        if (!res.ok) throw new Error("Telemetry fetch failed");
        const payload = await res.json();
        if (mounted) {
          setDataPoints((prev) => [...prev.slice(-19), payload]);
          setIsLoading(false);
        }
      } catch (err) {
        console.error("Telemetry streaming error:", err);
      }
    };

    fetchMetrics();
    const interval = setInterval(fetchMetrics, intervalMs);
    return () => {
      mounted = false;
      clearInterval(interval);
    };
  }, [intervalMs]);

  const summary = useMemo(() => {
    if (dataPoints.length === 0) return { avgRevenue: 0, peakUsers: 0 };
    const avgRevenue = dataPoints.reduce((acc, p) => acc + p.revenue, 0) / dataPoints.length;
    const peakUsers = Math.max(...dataPoints.map((p) => p.activeUsers));
    return { avgRevenue: Math.round(avgRevenue), peakUsers };
  }, [dataPoints]);

  return { dataPoints, summary, isLoading };
}

export interface CartItem {
  id: string;
  title: string;
  price: number;
  quantity: number;
  stock: number;
}

export interface CartState {
  items: Map<string, CartItem>;
  totalAmount: number;
  totalQuantity: number;
  isSyncing: boolean;
}

export type CartAction =
  | { type: "ADD_ITEM"; payload: CartItem }
  | { type: "UPDATE_QTY"; payload: { id: string; quantity: number } }
  | { type: "REMOVE_ITEM"; payload: { id: string } }
  | { type: "CLEAR_CART" };

export function cartReducer(state: CartState, action: CartAction): CartState {
  const nextItems = new Map(state.items);

  switch (action.type) {
    case "ADD_ITEM": {
      const existing = nextItems.get(action.payload.id);
      if (existing) {
        const newQty = Math.min(existing.quantity + 1, action.payload.stock);
        nextItems.set(action.payload.id, { ...existing, quantity: newQty });
      } else {
        nextItems.set(action.payload.id, { ...action.payload, quantity: 1 });
      }
      break;
    }
    case "UPDATE_QTY": {
      const target = nextItems.get(action.payload.id);
      if (target && action.payload.quantity > 0) {
        nextItems.set(action.payload.id, { ...target, quantity: action.payload.quantity });
      } else {
        nextItems.delete(action.payload.id);
      }
      break;
    }
    case "REMOVE_ITEM":
      nextItems.delete(action.payload.id);
      break;
    case "CLEAR_CART":
      nextItems.clear();
      break;
  }

  let totalAmount = 0;
  let totalQuantity = 0;
  for (const item of nextItems.values()) {
    totalAmount += item.price * item.quantity;
    totalQuantity += item.quantity;
  }

  return { items: nextItems, totalAmount: Number(totalAmount.toFixed(2)), totalQuantity, isSyncing: false };
}

