};

import * as React from "react";
import Editor, { useMonaco } from "@monaco-editor/react";

interface CodeWorkspaceProps {
  initialFile: string;
  activeLanguage: string;
  theme: "vs-dark" | "light";
  onCodeChange: (content: string) => void;
}

export function CodeWorkspace({ initialFile, activeLanguage, theme, onCodeChange }: CodeWorkspaceProps) {
  const monaco = useMonaco();

  React.useEffect(() => {
    if (!monaco) return;
    monaco.editor.setTheme(theme === "vs-dark" ? "vs-dark" : "vs");
    monaco.languages.typescript.typescriptDefaults.setDiagnosticsOptions({
      noSemanticValidation: false,
      noSyntaxValidation: false,
    });
  }, [monaco, theme]);

  return (
    <div className="h-full w-full overflow-hidden rounded-xl border border-zinc-800 bg-[#1e1e1e]">
      <Editor
        height="100%"
        language={activeLanguage}
        defaultValue={initialFile}
        theme={theme}
        options={{
          minimap: { enabled: true, side: "right" },
          fontSize: 13,
          lineNumbers: "on",
          scrollBeyondLastLine: false,
          fontFamily: "'JetBrains Mono', 'Fira Code', monospace",
          fontLigatures: true,
          cursorBlinking: "smooth",
          smoothScrolling: true,
        }}
        onChange={(value) => onCodeChange(value || "")}
      />
    </div>
  );
}

